```js workflow
const repo = "/home/exedev/email-os";
const coreDir = "/home/exedev/email-os-ux05-core";
const uiDir = "/home/exedev/email-os-ux05-ui";
const rules = "Read docs/ux-05-safe-bulk-processing.md completely; it is the approved implementation contract, including its four recommended decisions. Preserve UX-01..04, account/capability gates, explicit no-auto-read and composer safety. Synthetic tests only; no real mailbox/network/OAuth mutations, no pushing/PR/merging to main, no delegation. Read applicable skills when using mise. Use read for file examination and targeted edits. Long builds use background tools. Report actual evidence and limitations, not assumed success. Ask supervisor for scope-changing decisions; do not silently defer approved requirements.";
const seam = await runs.run("freeze-group-seam", {
  label: "Freeze group IPC contract",
  agent: "worker", cwd: coreDir, worktree: false,
  task: rules + "\nYou own the backend lane at branch work/ux-05-core, baseline 31ec046. First stage ONLY: inspect both stores and freeze a practical exact Rust DTO/error/IPC seam for the full UX-05 scope, covering setters, lookup by request ID, paginated group listing, group Undo with member statuses/skips, group links and supersession/eligibility. Implement DTO declarations, generate-types output, MailClient types/methods, tauri-client wrappers/error validation and transport tests as appropriate. You may edit crates/mail-core/src/dto.rs, error.rs, bin/generate-types.rs, src/lib/ipc/{generated,client,tauri-client}.ts, tests/tauri-client.test.ts; a focused Rust types module is allowed. Do NOT implement store algorithms/UI/browser-fake yet. Understand the algorithms enough not to freeze an impossible seam. Freeze exact command shapes before ending, commit your changes, and include full commit SHA and a compact seam explanation in final output. Finish with UX05_SEAM_READY only if committed and usable for parallel implementation; otherwise report blocked and omit that marker. It is acceptable for other implementers/fakes to be temporarily missing the new interface methods at this stage. Do not edit scope docs; supervisor owns them."
});
if (!seam.ok || !seam.output.includes("UX05_SEAM_READY")) return {blocked:"Contract stage incomplete", seam};
const lanes = await runs.all([
  {
    key:"implement-durable-groups", label:"Implement durable group execution and Undo",
    resume:seam.runId, cwd:coreDir, worktree:false,
    task:rules + "\nContinue backend implementation against your frozen seam. Exclusive ownership: crates/mail-core/**, src-tauri/**, src/lib/ipc/{generated,client,tauri-client}.ts and tests/tauri-client.test.ts. Do NOT edit UI/browser-fake or scope docs. Implement full contract in fixture and Gmail stores, migrations, bounded atomic acceptance/member rejections/savepoints, canonical idempotency and lost-response queries, immutable targets/preimages, latest top-level single/group/retry ordering, partial one-shot group Undo, persisted receipts/results/restart/query pagination, core/shell command forwarding/manifests/capabilities. Existing single Undo must not bypass group ordering. Capability checks before acceptance/execution. Add meaningful fake-clock/provider/storage tests for failure/unknown/restart/new replies/order/duplicate request/expiry. Freeze seam; if changing it becomes essential, ask supervisor before changing frontend-facing types. Run core tests/lint/contract, targeted native compilation/bridge tests if supported; report environment blockers. Commit all backend work to your lane. Final report include commit SHA, exact checks, residual gaps; finish UX05_CORE_READY only when the approved scope is implemented with no known blocking issues."
  },
  {
    key:"implement-selection-ui", label:"Implement selection and group recovery UI",
    agent:"worker", cwd:uiDir, worktree:false,
    task:rules + "\nYou own frontend lane branch work/ux-05-ui, baseline 31ec046. Before any changes, fast-forward this lane to the committed IPC seam from the backend worker: obtain its commit SHA from the following report and run git merge --ff-only <that SHA>. Do NOT merge a moving backend branch. Seam report:\n" + seam.output + "\nExclusive ownership: src/App.vue, src/components/**, src/composables/**, src/assets/**, src/lib/browsing-actions.ts, src/lib/ipc/browser-fake.ts, tests/** EXCEPT tests/tauri-client.test.ts (backend-owned); add focused frontend modules as needed. Do not edit generated/client/tauri-client/Rust/shell/scope docs. Implement complete selection UX and count/limit feedback, exact target resolver incl row-scoped actions, visible bulk scope in reader, escape precedence, context/session fencing, selection-one group semantics. Integrate typed group methods, immutable outstanding request/recovery on lost response, explicit pending single-or-group identity (not first-row fake), authoritative notice/Activity group detail/pagination/member recovery and partial Undo including compensation statuses/restart rehydration. Browser fake implements seam for synthetic tests and models failure/unknown/idempotency/expiry while disclosing non-durability. Preserve compact row disclosures/scroll/focus and existing single flows. Add selection/component/transport-fake/rendered regression tests. Use the seam exactly; ask supervisor if impossible. Run UI tests/typecheck/build and relevant rendered checks. Commit your lane changes; report checks and residual gaps. Finish UX05_UI_READY only when implemented with no known blocking issues."
  }
]);
if (!lanes[0].ok || !lanes[1].ok || !lanes[0].output.includes("UX05_CORE_READY") || !lanes[1].output.includes("UX05_UI_READY")) return {blocked:"Implementation lane incomplete", lanes};
const integration = await runs.run("integrate-ux05", {
  label:"Integrate group processing and validate",
  agent:"worker", cwd:repo, worktree:false,
  task:rules + "\nYou are the sole integration writer on feat/ux-05-safe-bulk-processing. Merge --no-ff work/ux-05-core and work/ux-05-ui into this feature branch (never main). Check worktrees are committed first. Resolve integration issues without dropping approved behavior. Run six checks from .pi/factory.json plus native compile/bridge checks if possible; keep exact evidence. Update docs/ux-05-safe-bulk-processing.md and docs/development.md with implemented status and honest validation ledger/native pending items. Commit any integration fixes and docs. No push. Backend report:\n" + lanes[0].output + "\nFrontend report:\n" + lanes[1].output + "\nFinish UX05_INTEGRATED only if integration and all locally supported validation pass, otherwise report exact blockers."
});
if (!integration.ok || !integration.output.includes("UX05_INTEGRATED")) return {blocked:"Integration incomplete", integration, lanes};
const reviews = await runs.all([
  {key:"review-group-safety",label:"Review durable group safety",agent:"reviewer",cwd:repo,worktree:false,task:"READ ONLY fresh review of UX-05 diff ed6b2d2..HEAD against docs/ux-05-safe-bulk-processing.md. Focus Rust/schema/Tauri/IPC safety: atomic acceptance, account gates, request collision/idempotency/lost responses, immutable message targets/preimages, migration/restart, member failures/unknowns, single/group/retry supersession, partial Undo/compensation/cancel race, child bypass and expiry. Report actionable P1/P2 bugs with file/line and concrete scenarios; note coverage gaps and mandatory human/runtime callouts. No edits or commits."},
  {key:"review-selection-scope",label:"Review selection and recovery UX",agent:"reviewer",cwd:repo,worktree:false,task:"READ ONLY fresh review of UX-05 diff ed6b2d2..HEAD against docs/ux-05-safe-bulk-processing.md. Focus frontend/fake/transport: selection stable IDs/range limits, click and key guards/IME, reader scope, row-scoped actions, context/account fences, lost acceptance response retained requests, group statuses/Undo compensation/restart notice, Activity pagination/recovery, accessibility and compact-row focus/layout regressions. Report actionable P1/P2 bugs with file/line and scenarios, test gaps, human/runtime callouts. No edits or commits."}
]);
if (!reviews[0].ok || !reviews[1].ok) return {blocked:"Review runtime incomplete", reviews, integration};
const fixes = await runs.run("address-ux05-review", {
  label:"Address review findings and revalidate",
  agent:"worker",cwd:repo,worktree:false,
  task:rules + "\nSole writer on integrated feature branch. Critically assess these independent reviews, fix verified blocking findings and add regression tests; document reason/evidence for any non-actionable findings. Do not reduce scope or hide failures. Re-run affected checks and the six factory checks; native checks where supported. Update validation ledger, commit fixes, no push. If implementation is incomplete, report it instead of claiming done.\nBACKEND REVIEW:\n" + reviews[0].output + "\nUI REVIEW:\n" + reviews[1].output + "\nFinal report commit SHA, addressed/deferred findings, checks, runtime limitations and clean status."
});
return {integration:integration.outputReference, reviews:reviews.map(r=>({runId:r.runId,outputReference:r.outputReference})), fixes, lanes:lanes.map(r=>({runId:r.runId,outputReference:r.outputReference})), artifactPaths:fixes.artifactPaths};
```

