            @click="emit('unarchive', op.conversation)"
          >
            Unarchive
          </button>
          <button
            v-if="gmailMode && actionsEnabled && canRetry(op.status)"
            type="button"
            :data-test="`activity-retry-${op.id}`"
            @click="emit('retry', op.id)"
          >
            Retry with a new request ID
          </button>
        </span>
      </li>
    </ul>
  </aside>
</template>

